class WebhookSubscriptionUpdateView(LoginRequiredMixin, UpdateView):
    model = WebhookSubscription
    fields = ['target_url', 'secret_token', 'is_active']
    template_name = 'webhooks/edit.html'

    def get_object(self, queryset=None):
        return get_object_or_404(
            WebhookSubscription,
            id=self.kwargs['pk'],
            organization=self.request.user.organization
        )
